effect.shader:
#define PI 3.14159265359
float hash(float n) {
return fract(sin(n) * 43758.5453123);
}
mat2 rot(float a) {
float s = sin(a), c = cos(a);
return mat2(c, -s, s, c);
}
struct ShardInfo {
float id;
vec2 moveDir;
float distToCut;
};
ShardInfo getShardInfo(vec2 p, float numCuts, float cutRadius) {
float id = 0.0;
vec2 moveAcc = vec2(0.0);
float minDist = 100.0;
int NUM_CUTS = int(numCuts);
for(int i = 0; i < 30; i++) {
if(i >= NUM_CUTS) break;
float fi = float(i);
float h1 = hash(fi + seed);
float h2 = hash(fi + seed * 5.0 + 99.0);
float angle = h1 * PI * 2.0;
vec2 n = vec2(cos(angle), sin(angle));
float off = (h2 - 0.5) * cutRadius;
float d = dot(p, n) - off;
minDist = min(minDist, abs(d));
float side = sign(d);
if(side > 0.0) {
id += pow(1.5, fi);
}
moveAcc += n * side;
}
vec2 randomDir = vec2(hash(id) - 0.5, hash(id + 1.0) - 0.5);
moveAcc += randomDir * 1.5;
return ShardInfo(id, normalize(moveAcc), minDist);
}
float drawSwipe(vec2 p, vec2 n, float off, float t, float hashSeed) {
vec2 tangent = vec2(-n.y, n.x);
float posAlongLine = dot(p, tangent);
float dir = step(0.5, hash(hashSeed)) * 2.0 - 1.0;
float swipe = (t * 12.0 - 6.0) * dir;
return smoothstep(-0.2, 0.2, (swipe - posAlongLine) * dir);
}
void main() {
vec2 texSize = inputImg.size;
vec2 uv = acScreenNorm;
vec2 p = (acScreenNorm - 0.5) * vec2(texSize.x / texSize.y, 1.0);
float t = progress * 4.0;
float slashEnd = 1.2;
float explodeStart = 1.4;
if (progress <= 0.001) {
gl_FragColor = texture2DCv(inputImg.texture, uv);
return;
}
float force = 0.0;
if(t > explodeStart) {
float et = t - explodeStart;
force = et * et * explosionSpeed + et * 0.2;
}
int NUM_CUTS = int(sliceCount);
ShardInfo destInfo = getShardInfo(p, sliceCount, sliceRadius);
float zScale = 1.0;
if(force > 0.0) {
zScale = 1.0 + (hash(destInfo.id) - 0.5) * force;
zScale = max(0.1, zScale);
}
vec2 offset = destInfo.moveDir * force;
vec2 srcP = (p - offset) / zScale;
ShardInfo srcInfo = getShardInfo(srcP, sliceCount, sliceRadius);
bool isSameShard = abs(destInfo.id - srcInfo.id) < 0.1;
vec3 col = vec3(0.0);
float alpha = 0.0;
if (isSameShard) {
vec2 srcUV = srcP / vec2(texSize.x / texSize.y, 1.0) + 0.5;
if(srcUV.x >= 0.0 && srcUV.x <= 1.0 && srcUV.y >= 0.0 && srcUV.y <= 1.0) {
vec4 texCol = texture2DCv(inputImg.texture, srcUV);
col = texCol.rgb;
alpha = texCol.a;
if(force > 0.0) {
float dim = 1.0 / (1.0 + force * 0.5);
float glint = sin(force * 5.0 + hash(destInfo.id)*10.0) * 0.5 + 0.5;
col *= dim * (0.8 + 0.4*glint);
}
}
}
if (t < explodeStart + 0.5) {
float accumulatedGlow = 0.0;
for(int i = 0; i < 30; i++) {
if(i >= NUM_CUTS) break;
float fi = float(i);
float h1 = hash(fi + seed);
float h2 = hash(fi + seed * 5.0 + 99.0);
float angle = h1 * PI * 2.0;
vec2 n = vec2(cos(angle), sin(angle));
float off = (h2 - 0.5) * sliceRadius;
float d = abs(dot(p, n) - off);
float myStart = (fi / float(NUM_CUTS)) * slashEnd;
if(t > myStart) {
float locT = t - myStart;
float line = 0.0015 / (d + 0.0001);
float swipe = drawSwipe(p, n, off, locT, h1);
float fade = exp(-locT * 4.0);
accumulatedGlow += line * swipe * fade * 2.0;
}
}
col += glowColor.rgb * accumulatedGlow * glowIntensity;
alpha = max(alpha, accumulatedGlow * glowIntensity);
}
float flash = smoothstep(explodeStart, explodeStart + 0.05, t) *
(1.0 - smoothstep(explodeStart + 0.05, explodeStart + 0.4, t));
if (flashEnabled) {
col += vec3(1.0) * flash;
alpha = max(alpha, flash);
}
gl_FragColor = vec4(col, alpha);
}
